	@Test
	void singleSourceResultShapeDependsOnOriginalQueryType() {
		var queryInfo = mock(QueryInfo.class);
		var query = new SingleSourceQuery(pattern("s", "p", "o"), mock(Endpoint.class), queryInfo);
		var analysis = QueryAlgebraBindingAnalysis.withGuaranteedInputNames(query, Set.of("entry"));
		when(queryInfo.getQueryType()).thenReturn(QueryType.SELECT);
		assertEquals(Set.of("s", "p", "o"), analysis.outputFacts(query).possibleOutputs());
		assertTrue(analysis.outputFacts(query).retainedInputNames().isEmpty());

		when(queryInfo.getQueryType()).thenReturn(QueryType.ASK);
		analysis.invalidate();
		assertTrue(analysis.outputFacts(query).possibleOutputs().isEmpty());
		assertTrue(analysis.outputFacts(query).retainedInputNames().isEmpty());
		assertTrue(query.getBindingNames().isEmpty());
		assertTrue(query.getAssuredBindingNames().isEmpty());

		when(queryInfo.getQueryType()).thenReturn(QueryType.CONSTRUCT);
		analysis.invalidate();
		assertEquals(Set.of("subject", "predicate", "object", "context"),
				analysis.outputFacts(query).possibleOutputs());
		assertEquals(Set.of("subject", "predicate", "object"), analysis.outputFacts(query).guaranteedOutputs());
		assertEquals(Set.of("subject", "predicate", "object", "context"), query.getBindingNames());
		assertEquals(Set.of("subject", "predicate", "object"), query.getAssuredBindingNames());
	}

